<?php
namespace App\Http\Controllers\SupervisorPortal;
use App\Http\Controllers\Controller; use App\Http\Controllers\SupervisorPortal\Concerns\AuthorizesAssignedStudents; use App\Models\GuardianCall; use App\Models\Student; use App\Services\AuditService; use App\Services\ParentNotificationService; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Validation\Rule; use Illuminate\View\View;
class GuardianCallController extends Controller { use AuthorizesAssignedStudents; public function index(Request $r): View { $ids=$r->user()->supervisedClassrooms()->pluck('classrooms.id'); return view('supervisor.calls.index',['calls'=>GuardianCall::with('student.user')->whereHas('student',fn($q)=>$q->whereIn('classroom_id',$ids))->latest()->paginate(30),'students'=>Student::with(['user','classroom'])->whereIn('classroom_id',$ids)->where('status','active')->get()]); } public function storeDirect(Request $r,ParentNotificationService $notifications): RedirectResponse { $r->validate(['student_id'=>['required','integer','exists:students,id']]); return $this->store($r,Student::findOrFail($r->integer('student_id')),$notifications); } public function store(Request $r,Student $student,ParentNotificationService $notifications): RedirectResponse { $this->authorizeStudent($r,$student); $d=$r->validate(['category'=>['required','string','max:40'],'reason'=>['required','string','max:255'],'details'=>['nullable','string','max:5000'],'guardian_visible_details'=>['nullable','string','max:5000'],'meeting_date'=>['nullable','date','after_or_equal:today']]); $call=GuardianCall::create($d+['student_id'=>$student->id,'supervisor_id'=>$r->user()->id,'status'=>'pending','requested_date'=>today()]); AuditService::record('created','guardian_calls',$call); $notifications->sendToGuardians($student,['title'=>'استدعاء ولي الأمر','body'=>'تم طلب حضور ولي الأمر للطالب '.$student->user->name.'.','url'=>route('parent.guardian-calls',['student'=>$student->id]),'category'=>'guardian_call']); return back()->with('success','تم إنشاء الاستدعاء وإبلاغ ولي الأمر.'); } public function update(Request $r,GuardianCall $guardianCall): RedirectResponse { $this->authorizeStudent($r,$guardianCall->student); $d=$r->validate(['status'=>['required',Rule::in(['pending','notified','scheduled','completed','cancelled'])],'meeting_date'=>['nullable','date','after_or_equal:requested_date'],'guardian_response'=>['nullable','string','max:5000']]); $old=$guardianCall->getAttributes(); $guardianCall->update($d+['resolved_at'=>in_array($d['status'],['completed','cancelled'])?now():null]); AuditService::record('updated','guardian_calls',$guardianCall,$old); return back()->with('success','تم تحديث حالة الاستدعاء.'); } }
